// Returns the oldest key for a user if OATHPrioritizedModules is not set
func getOldestKeyForUser(userID string) (string, error) {
	// Fetch keys from the database without a specific sort order
	keys, err := db.GetKeysForUser(userID)
	if err != nil {
		return "", err
	}

	// If no keys are found, return an empty string
	if len(keys) == 0 {
		return "", nil
	}

	// Sort the keys by their creation time (assuming each key has a creation time field)
	sort.Slice(keys, func(i, j int) bool {
		return keys[i].CreatedAt.Before(keys[j].CreatedAt)
	})

	// Return the oldest key
	return keys[0].Key, nil
}
